import { useState } from 'react';
import { useStore } from '../context/StoreContext';

function AuthModal({ onClose }) {
  const { showToast } = useStore();
  const [mode, setMode] = useState('login');
  const [otpMode, setOtpMode] = useState(false);
  const [form, setForm] = useState({ name: '', email: '', phone: '', password: '', confirm: '' });
  const [error, setError] = useState('');

  const updateField = (field, value) => {
    setForm((current) => ({ ...current, [field]: value }));
    setError('');
  };

  const submit = (event) => {
    event.preventDefault();
    if (!/\S+@\S+\.\S+/.test(form.email)) {
      setError('Please enter a valid email address.');
      return;
    }
    if (form.password.length < 6) {
      setError('Password must contain at least 6 characters.');
      return;
    }
    if (mode === 'signup') {
      if (!form.name.trim()) {
        setError('Full name is required.');
        return;
      }
      if (form.password !== form.confirm) {
        setError('Password and confirm password do not match.');
        return;
      }
      setOtpMode(true);
      return;
    }
    showToast('Logged in successfully', 'success');
    onClose();
  };

  const verifyOtp = () => {
    showToast('Account verified successfully', 'success');
    onClose();
  };

  return (
    <div className="modal-backdrop" role="presentation" onMouseDown={onClose}>
      <section className="auth-modal card" role="dialog" aria-modal="true" aria-label="Authentication" onMouseDown={(event) => event.stopPropagation()}>
        <button className="modal-close" type="button" onClick={onClose} aria-label="Close authentication">×</button>

        {!otpMode ? (
          <>
            <div className="auth-header">
              <span className="eyebrow">Secure account</span>
              <h2>{mode === 'login' ? 'Welcome back' : 'Create your Tech Store account'}</h2>
              <p className="muted">Use your account to save addresses, track orders, and receive AI recommendations.</p>
            </div>

            <div className="auth-tabs">
              <button className={mode === 'login' ? 'active' : ''} onClick={() => setMode('login')} type="button">Login</button>
              <button className={mode === 'signup' ? 'active' : ''} onClick={() => setMode('signup')} type="button">Signup</button>
            </div>

            <form className="auth-form" onSubmit={submit}>
              {mode === 'signup' && (
                <label>
                  Full Name
                  <input className="input" value={form.name} onChange={(event) => updateField('name', event.target.value)} placeholder="Enter your full name" />
                </label>
              )}
              <label>
                Email Address
                <input className="input" value={form.email} onChange={(event) => updateField('email', event.target.value)} placeholder="name@example.com" />
              </label>
              {mode === 'signup' && (
                <label>
                  Phone Number
                  <input className="input" value={form.phone} onChange={(event) => updateField('phone', event.target.value)} placeholder="03XXXXXXXXX" />
                </label>
              )}
              <label>
                Password
                <input className="input" type="password" value={form.password} onChange={(event) => updateField('password', event.target.value)} placeholder="Enter password" />
              </label>
              {mode === 'signup' && (
                <label>
                  Confirm Password
                  <input className="input" type="password" value={form.confirm} onChange={(event) => updateField('confirm', event.target.value)} placeholder="Confirm password" />
                </label>
              )}
              {error && <div className="auth-error">{error}</div>}
              <button className="btn btn-primary" type="submit">{mode === 'login' ? 'Login' : 'Create Account'}</button>
            </form>

            <div className="auth-extra">
              {mode === 'login' ? <button type="button">Forgot password?</button> : <span>Password strength is checked before signup.</span>}
            </div>
          </>
        ) : (
          <div className="otp-screen">
            <div className="otp-icon">🔐</div>
            <h2>Verify your account</h2>
            <p className="muted">Enter the 6 digit code sent to your email address.</p>
            <div className="otp-inputs" aria-label="OTP code inputs">
              {[1, 2, 3, 4, 5, 6].map((digit) => (
                <input key={digit} maxLength="1" aria-label={`OTP digit ${digit}`} />
              ))}
            </div>
            <button className="btn btn-primary" type="button" onClick={verifyOtp}>Verify Code</button>
            <small>Resend code in 00:47</small>
          </div>
        )}
      </section>
    </div>
  );
}

export default AuthModal;
